app.addEventListener('click',e=>{const alert=e.target.closest('[data-quote-alert-target]');if(alert){e.preventDefault();const id=alert.dataset.quoteAlertTarget;professionalActiveFilter='pending';const jump=()=>{const target=document.getElementById('pro-pique-'+id);if(target){target.scrollIntoView({behavior:'smooth',block:'center'});target.classList.add('quote-request-highlight');setTimeout(()=>target.classList.remove('quote-request-highlight'),1800);}};if(route().name!=='inicio'){go('inicio');setTimeout(jump,80);}else{jump();}return;}const el=e.target.closest('button');if(!el)return;if(el.hasAttribute('data-filter-applications')){proposalsOnlyApplications=!proposalsOnlyApplications;render();return;}if(el.hasAttribute('data-dashboard-all')){dashboardFilter='all';dashboardPriority=null;render();return;}if(el.dataset.dashboardPriority){dashboardPriority=dashboardPriority===el.dataset.dashboardPriority?null:el.dataset.dashboardPriority;render();return;}if(el.dataset.dashboardFilter){dashboardFilter=route().name==='pedidos'&&dashboardFilter===el.dataset.dashboardFilter?'all':el.dataset.dashboardFilter;if(route().name!=='pedidos'){dashboardOwner=authUser?.id;piquesTab='personal';piquesDashboardTab='personal';go('pedidos');if(['resolved','archived'].includes(dashboardFilter))requestAnimationFrame(()=>document.getElementById('piques-'+dashboardFilter)?.scrollIntoView({block:'start'}));}else render();return;}if(el.dataset.requesterState){requesterStates[el.dataset.requesterSection]=el.dataset.requesterState;render();return;}if(el.dataset.applicationDecision){decideApplication(el);return;}if(el.dataset.quoteDecision){decideQuote(el);return;}if(el.dataset.applyOrder){applyToPique(el);return;}if(el.dataset.sendQuote){sendProfessionalQuote(el);return;}if(el.hasAttribute('data-new')){draft={category:el.dataset.new,description:'',zone:'',urgency:'Hoy'};step=0;go('nuevo');}if(el.hasAttribute('data-prev')){capture();step=Math.max(0,step-1);render();}if(el.dataset.orderFilter){ordersFilter=el.dataset.orderFilter;render();}if(el.dataset.proPiqueFilter){professionalPiquesFilter=el.dataset.proPiqueFilter;render();}if(el.dataset.activePiqueFilter){professionalActiveFilter=professionalActiveFilter===el.dataset.activePiqueFilter?'all':el.dataset.activePiqueFilter;professionalDashboardFilter='active';render();}if(el.dataset.sort){sort=el.dataset.sort;render();}if(el.dataset.profileTab){profileTab=el.dataset.profileTab;render();app.querySelector(`[data-profile-tab="${profileTab}"]`).focus();}if(el.dataset.requestQuote){requestQuote(el.dataset.order,el.dataset.requestQuote);return;}if(el.dataset.choose)go('elegir/'+el.dataset.order+'/'+el.dataset.choose);if(el.dataset.confirm){const o=orders.find(o=>o.id===el.dataset.order);if(o){o.selected=el.dataset.confirm;o.status='selected';save();render();}}if(el.hasAttribute('data-reset')){if(window.confirm('¿Restablecer la demo? Se borrarán los pedidos de prueba guardados en este navegador.')){orders=referenceOrders.map(normalizeOrder);save();go('inicio');toast('Datos de ejemplo restablecidos.');}}});
