function professionalDashboard(){
 if(professionalDashboardFilterOwner!==authUser?.id){professionalDashboardFilter='all';professionalDashboardFilterOwner=authUser?.id;}
 const rows=matchingRequestsOwner===authUser.id?matchingRequests:[];
 const executingCount=rows.filter(o=>o.quoteStatus==='accepted').length;
 const counts=[['active',rows.filter(o=>['accepted','applied','pending','quoted'].includes(o.quoteStatus)&&o.quoteStatus!=='accepted').length,'PIQUES ABIERTOS'],['unfulfilled',professionalHistoryOwner===authUser.id?professionalUnfulfilled.length:null,'PIQUES ARCHIVADOS'],['resolved',professionalResolvedOwner===authUser.id?professionalResolvedCount:null,'RESUELTOS']];
 if(['all','active'].includes(professionalDashboardFilter)&&counts[0][1]===0&&executingCount===0){if((counts[1][1]||0)>0)professionalDashboardFilter='unfulfilled';else if((counts[2][1]||0)>0)professionalDashboardFilter='resolved';}
 const p=professionalAccount;
 return `<section class="dashboard-welcome dashboard-welcome-columns professional-dashboard"><div class="dashboard-person"><span class="dashboard-avatar">${p.photo?`<img src="${esc(p.photo)}" alt="Tu foto">`:esc(((p.firstName||'')[0]||'P')+((p.lastName||'')[0]||''))}</span><div class="dashboard-identity"><h2>${esc(currentFirstName())}, ${route().name==='pedidos'?'MIRA TU ACTIVIDAD.':'ESTE ES TU PERFIL.'}</h2></div></div><div class="dashboard-stats">${counts.filter(([id,count])=>id==='active'||count===null||count>0).map(([id,count,label])=>`<button type="button" data-pro-summary="${id}" ${count===0?'disabled aria-disabled="true"':''}><strong>${homePiqueCounter(count??'—')}</strong><span>${(count===1?label.replace(/ABIERTOS$/,'ABIERTO').replace(/ARCHIVADOS$/,'ARCHIVADO').replace(/RESUELTOS$/,'RESUELTO'):label).replace(/^PIQUES? /,'')}</span></button>`).join('')}${executingCount?`<div class="dashboard-execution-count" role="button" tabindex="0" data-highlight-execution><strong>${homePiqueCounter(executingCount)}</strong><span>¡EN MARCHA!</span></div>`:''}</div></section>`;
}
app.addEventListener('click',e=>{const b=e.target.closest('[data-pro-summary]');if(!b)return;e.stopImmediatePropagation();professionalDashboardFilter=b.dataset.proSummary==='created'?'all':b.dataset.proSummary;if(['active','all'].includes(professionalDashboardFilter))professionalActiveFilter='all';if(['applied','quoting','coordinating'].includes(professionalDashboardFilter))professionalActiveFilter=professionalDashboardFilter;piquesTab='professional';piquesDashboardTab='professional';if(route().name==='pedidos')render();else go('pedidos');const target=professionalDashboardFilter==='unfulfilled'?'#professional-unfulfilled':professionalDashboardFilter==='resolved'?'#professional-resolved':'.professional-active-section';requestAnimationFrame(()=>document.querySelector(target)?.scrollIntoView({behavior:'smooth',block:'start'}));},true);

function professionalUnfulfilledSection(){
 const rows=professionalHistoryOwner===authUser?.id?professionalUnfulfilled:[];
 if(!rows.length)return '';
 return `<section id="professional-unfulfilled" class="orders-history dashboard-orders"><div class="quote-requests-heading stacked"><div class="pique-section-title"><h2>${rows.length===1?'PIQUE ARCHIVADO':'PIQUES ARCHIVADOS'}</h2><span class="pique-section-count">${rows.length}</span></div></div><div class="unfulfilled-order-list">${rows.map(o=>{const urgent=['Hoy','Ahora'].includes(o.urgency);return `<article class="panel order requester-photo-card ${categoryThemeClass(o.category)}"><div class="pending-order-layout unfulfilled-pique-layout resolved-card-columns"><div class="pending-order-main"><div class="pique-state-row">${deadlineTag(o)}</div><h3 class="request-title" data-fit-card-title>${esc(o.title||o.description)}</h3><p class="order-description">${esc(o.description)}</p></div><div class="pique-card-divider" aria-hidden="true"></div><div class="pending-order-meta">${resolvedRequestMetaTags(o)}</div><p class="archive-policy-note ${o.unfulfilledReason?'rejected':urgent?'urgent':'agenda'}">${o.unfulfilledReason?esc(o.unfulfilledReason):urgent?'LOS PIQUES CON URGENCIA SE ARCHIVAN A LAS 24HS DE PUBLICADOS.':'LOS PIQUES SIN URGENCIA SE ARCHIVAN A LOS 7 DÍAS DE PUBLICADOS.'}</p></div></article>`;}).join('')}</div></section>`;
}
function resolvedFinalizationDate(o){
 const row=Array.isArray(o.pique_coordination)?o.pique_coordination[0]:o.pique_coordination;
 const value=row?.updated_at;
 if(!value||!Number.isFinite(new Date(value).getTime()))return 'SIN ESPECIFICAR';
 return new Intl.DateTimeFormat('es-UY',{timeZone:'America/Montevideo',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(value));
}
function professionalResolvedSection(){
 const rows=professionalResolvedOwner===authUser?.id?professionalResolvedPiques:[];if(!rows.length)return '';
 return `<section id="professional-resolved" class="orders-history dashboard-orders"><div class="quote-requests-heading stacked"><div class="pique-section-title"><h2>${rows.length===1?'PIQUE RESUELTO':'PIQUES RESUELTOS'}</h2><span class="pique-section-count">${rows.length}</span></div></div><div class="dashboard-order-list">${rows.map(o=>`<article class="panel order requester-photo-card professional-resolved-card ${categoryThemeClass(o.category)}"><div class="resolved-card-columns"><div><div class="pique-state-row"><span class="deadline-tag completion-finalized-tag">FINALIZADO</span></div><h3 class="request-title" data-fit-card-title>${esc(o.title||o.description)}</h3><p class="order-description">${esc(o.description)}</p></div><div class="pique-card-divider" aria-hidden="true"></div><div class="resolved-card-details">${resolvedRequestMetaTags(o)}</div></div><div class="resolved-card-price"><span class="price-tag"><small>PRECIO ACORDADO</small><strong>${o.quotedPrice!=null?money(o.quotedPrice):'SIN ESPECIFICAR'}</strong></span><span class="resolved-finalization-hint"><small>FECHA DE FINALIZACIÓN</small><strong>${resolvedFinalizationDate(o)}</strong></span></div><div class="resolved-details-separator" aria-hidden="true"></div><a class="btn requester-open full" href="#coordinar/${encodeURIComponent(o.id)}">${svg('search')}<span>VER MÁS DETALLES</span></a></article>`).join('')}</div></section>`;
}

app.addEventListener('click',async e=>{const b=e.target.closest('[data-complete-order]');if(!b)return;if(!confirmCompletion())return;b.disabled=true;const owner=authUser?.id;try{const {data,error}=await authClient.from('service_requests').update({status:'completed'}).eq('id',b.dataset.completeOrder).eq('user_id',owner).eq('status','selected').select('id');if(error||!data?.length)throw Error('closed');if(authUser?.id!==owner)return;await loadRemoteOrders();render();toast('PIQUE RESUELTO.');}catch{toast('NO SE PUDO COMPLETAR. EL PIQUE PUEDE HABER VENCIDO.');await loadRemoteOrders();render();}});
function confirmCompletion(){return window.confirm('¿EL TRABAJO YA ESTÁ TERMINADO?');}
setInterval(()=>{if(!authUser||!['inicio','cuenta','pedidos','propuestas'].includes(route().name))return;const expired=[...userOrders(),...matchingRequests].some(o=>o.status!=='archived'&&orderIsArchived(o));if(expired){loadRemoteOrders().then(()=>loadMatchingRequests());}},30000);

function publicCompletedWorkCard(work,p){const review=p.realReviews?.find(r=>r.request_id===work.id);return '<article class="public-resolved-work-card"><div class="public-work-heading"><h3>'+esc(work.title)+'</h3></div><p class="public-profile-bio">'+esc(work.description||'')+'</p><div class="public-work-score"><strong>PUNTUACIÓN</strong><span>'+(review?'★ '+Number(review.rating).toFixed(1).replace('.',','):'SIN VALORACIÓN')+'</span></div></article>';}
function publicWorkPhotos(p){return (p.resolvedPiques||[]).map(work=>'<article class="public-resolved-work-card public-photo-card"><h3>'+esc(work.title)+'</h3><div class="public-work-gallery">'+(work.completion_photos||[]).map((src,i)=>'<button type="button" class="completion-photo-tile" data-public-work-photo="'+esc(work.id)+'" data-photo-index="'+i+'" aria-label="Ampliar foto '+(i+1)+'"><img src="'+esc(src)+'" alt="Foto del trabajo terminado" loading="lazy"><span>FOTO '+(i+1)+' · AMPLIAR</span></button>').join('')+'</div></article>').join('')||publicProfileEmpty(publicProfessionalName(p)+' AÚN NO PUBLICÓ FOTOS.');}

function resolvedRequestMetaTags(o){
 const parts=publicationLabel(o).split(' · '),date=parts[0]||'SIN ESPECIFICAR',time=parts[1]||'SIN ESPECIFICAR';
 const tags=[[categoryEmoji(o.category),o.category],['📍',String(o.zone||'SIN ESPECIFICAR').replace(/,?\s*MONTEVIDEO\s*$/i,'')]].map(([icon,text])=>'<span class="pique-meta-tag"><span class="meta-icon" aria-hidden="true">'+icon+'</span><span class="meta-text">'+esc(text)+'</span></span>').join('');
 return '<div class="pique-meta-tags">'+tags+'<span class="pique-meta-tag metadata-date-time"><span class="meta-icon" aria-hidden="true">📅</span><span class="meta-text"><span>'+esc(date)+'</span><span>'+esc(time)+'</span></span></span></div>';
}

function homePiqueCounter(count){return `<svg class="home-pique-counter" viewBox="0 0 50 65" aria-label="${count} ${count===1?'pique':'piques'}"><path fill="currentColor" stroke="none" d="M3 60V27C3 12 13 2 26 2s23 10 23 24-10 24-24 24h-8L7 63c-2 2-4 1-4-3Z"/><text x="26" y="33" text-anchor="middle" fill="white" stroke="none" font-family="Nunito Sans,Arial,sans-serif" font-size="25" font-weight="700">${count}</text></svg>`;}

function applySectionLogoCounts(){if(!['inicio','pedidos'].includes(route().name))return;app.querySelectorAll('.dashboard-section-heading,.pique-section-title,.requester-home-section .section-heading').forEach(row=>{const title=row.querySelector('h2');const count=row.querySelector('span');if(!title||!count||count.querySelector('svg')||!/^PIQUES?\b/.test(title.textContent))return;const value=Number(count.textContent.trim());if(!Number.isFinite(value))return;count.remove();title.textContent=title.textContent.replace(/^P/,'').trim();count.classList.add('section-logo-count');count.innerHTML=homePiqueCounter(value);row.prepend(count);});}

function myPiquesBack(){return `<a class="btn requester-open full profile-my-piques-button details-my-piques-button" href="#pedidos">${document.querySelector('.nav-pique-logo')?.outerHTML||''}<span>VOLVER A MIS PIQUES</span></a>`;}

document.addEventListener('click',e=>{const link=e.target.closest('a[href="#pedidos"]');if(!link)return;dashboardFilter='pending';dashboardPriority=null;professionalDashboardFilter='all';professionalActiveFilter='all';if(route().name==='pedidos')render();});

function piqueDetailBack(id){return `<a class="btn requester-open full profile-my-piques-button details-my-piques-button" href="#propuestas/${encodeURIComponent(id)}">${document.querySelector('.nav-pique-logo')?.outerHTML||''}<span>VOLVER AL PIQUE</span></a>`;}

function syncExecutionColumnHeight(){app.querySelectorAll(".professional-card-coordinating:not(.professional-waiting-schedule):not(.coordination-three-card)").forEach(card=>{const left=card.querySelector(":scope>.quote-request-left"),right=card.querySelector(":scope>.quote-request-controls");if(!left||!right)return;card.style.setProperty("--pique-copy-height",getComputedStyle(left).height);});}
window.addEventListener("resize",()=>requestAnimationFrame(syncExecutionColumnHeight));
const executionColumnObserver=new ResizeObserver(syncExecutionColumnHeight);
const executionCardObserver=new MutationObserver(()=>{app.querySelectorAll(".professional-card-coordinating>.quote-request-left").forEach(left=>executionColumnObserver.observe(left));});
executionCardObserver.observe(app,{childList:true,subtree:true});

function highlightExecutionCard(){const professional=!!app.querySelector('.professional-dashboard-band,.professional-dashboard');if(professional){professionalDashboardFilter='execution';professionalActiveFilter='all';}else{dashboardFilter='execution';dashboardPriority=null;}const focusCard=()=>requestAnimationFrame(()=>{const card=app.querySelector('.professional-profile-process .professional-card-coordinating,.requester-execution-section article,.requester-home-progress')?.closest('article');if(!card)return;card.classList.remove('execution-card-highlight');void card.offsetWidth;card.classList.add('execution-card-highlight');card.scrollIntoView({behavior:'smooth',block:'center'});});if(route().name!=='pedidos'){piquesDashboardTab=professional?'professional':'requester';window.addEventListener('hashchange',focusCard,{once:true});go('pedidos');}else{render();focusCard();}}
document.addEventListener('click',e=>{if(!e.target.closest('[data-highlight-execution]'))return;e.stopImmediatePropagation();highlightExecutionCard();},true);
document.addEventListener('keydown',e=>{if(!e.target.closest('[data-highlight-execution]')||!['Enter',' '].includes(e.key))return;e.preventDefault();highlightExecutionCard();});

function publicProfileEmpty(message){return `<p class="public-profile-empty" role="status">${svg("info")}<span>${esc(message)}</span></p>`;}

function publicProfessionalName(p){return String(p.name||"EL PROFESIONAL").trim().split(/\s+/)[0].toUpperCase();}
